INSERT INTO characters (slug,name,team,creator,owner_id,tags,appears_in,data,url_slug,status,updated_at,created_at) VALUES
('goc-physics','GOC Physics','townsfolk','legitch',NULL,'','SCP Fragmented Veil','{"slug":"goc-physics","name":"GOC Physics","team":"townsfolk","ability":"Twice per game, at night*, you may be safe from the Demon & the 1st non-Demon to choose you until tomorrow is drunk then dies.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"GOC Physics is the division of the SCP Foundation that investigates the physics and science of anomalies, in order to harness said power for the foundation.","summaryBullets":["The GOC Physics cannot die from the abilities whilst they''re using their ability that night. So, if anything attacks them at night, nothing happens.","Whilst the GOC Physics is using their ability, the first time a player wakes to use their ability and chooses them, that player will die once the GOC Physics wakes. This excludes the Demon.","A protected player being marked to die the next night will die if not protected when it occurs."],"howToRun":["Each night except the first, remove the **TRAP SET** reminder token if it is present, and if any player is marked with the **HEXED** reminder, they {{i|die}} - mark them with the **DEAD** reminder. Then, wake the GOC Physics. They either shake their head no or shake their head yes. Put them to sleep.","If the GOC Physics shook their head yes, mark them with the **TRAP SET** reminder token. **GOC Physics loses an ability charge** - mark them with either the **1 USE** reminder, or if they already have that reminder, the **NO ABILITY** reminder and remove their night token from the night sheet {{i|(GOC Physics won''t wake again.)}}","If the GOC Physics would die at night whilst they have the **TRAP SET** reminder, they remain alive.","At night, if a non-Demon player chooses to use their ability on the GOC Physics with the **TRAP SET** reminder and nobody is marked with the **HEXED** reminder, this player is **drunk** will {{i|die}} the next night - mark them with the **HEXED** reminder."],"quote":"Fuckin'' dieeeeee....","iconBy":"le_nuberto","jinxes":[{"name":"Leviathan","align":"evil","text":"If Leviathan nominates and executes the GOC Physics whilst they activated their ability last night, they do not die.","id":"leviathan"},{"name":"Riot","align":"evil","text":"If a Riot player nominates and kills the GOC Physics whilst they activated their ability last night, they do not die.","id":"riot"},{"name":"Summoner","align":"evil","text":"The GOC Physics cannot kill the Summoner.","id":"summoner"},{"name":"Matsuraid","align":"evil","text":"If the Matsuraid is in play, votes for the GOC Physics secretly do not count whilst they activated their ability last night.","id":"matsuraid_hblreleased"},{"name":"Ketos","align":"evil","text":"If Ketos correctly guesses the GOC Physics whilst they activated their ability last night, the end does not come sooner.","id":"ketos_the_bootleggers_anthology"}],"customBoxes":[{"title":"Credit","content":"Ability: @legitch, SC2Mafia. Image: @le_nuberto"},{"title":"In the almanac JSON","content":"**Ability:** Twice per game, at night*, you may be safe from death tonight & the 1st non-Demon to choose you until tomorrow is drunk then dies."},{"title":"Alternative JSON & How to Run","content":"For if you want the GOC Physics to be able to have a stronger killing potential with a reduced scope, use this JSON.\n\nEach night except the first, remove the TRAP SET reminder token if it is present, and if any players are marked with the HEXED reminder, they die - mark them with the DEAD reminder. Then, wake the GOC Physics. They either shake their head no or shake their head yes. Put them to sleep.\n\nIf the GOC Physics shook their head yes, mark them with the TRAP SET reminder token. GOC Physics has used their ability - mark them with either the NO ABILITY reminder and remove their night token from the night sheet (GOC Physics won''t wake again.)\n\nIf the Demon attacks the GOC Physics whilst they have the TRAP SET reminder, they remain alive.\n\nIn other editions, Demons may have abilities other than killing. The GOC Physics is also protected from all other harmful effects of the Demon''s ability, such as poisoning or turning them evil.\n\nAt night, if a non-Demon player chooses to use their ability on the GOC Physics with the TRAP SET reminder, this player is drunk will die the next night - mark them with the HEXED reminder.\n\n**GOC Physics █~** (Townsfolk)\nOnce per game, at night*, you may be safe from the Demon & all non-Demons to choose you until tomorrow is drunk then dies.\n\n**Other nights:** If a player is marked ''hexed'': they die. If the GOC Physics has not yet fully used their ability: The GOC Physics shows a ''no'' head signal, or shows a ''yes'' head signal. If the GOC Physics showed a ''yes'' head signal, mark them ''Trap set''.\n**Reminders:** Trap set, Hexed, Hexed, Dead, Dead, No ability\n**Credit:** Ability: @legitch, SC2Mafia. Image: @le_nuberto\n\n**Jinxes:**\nLeviathan: If Leviathan nominates and executes the GOC Physics whilst they activated their ability last night, they do not die.\nRiot: If a Riot player nominates and kills the GOC Physics whilst they activated their ability last night, they do not die.\nSummoner: The GOC Physics cannot kill the Summoner.\nMatsuraid: If the Matsuraid is in play, votes for the GOC Physics secretly do not count whilst they activated their ability last night.\nKetos: If Ketos correctly guesses the GOC Physics whilst they activated their ability last night, the end does not come sooner."}],"firstNight":0,"otherNight":54.904515,"reminders":["Trap set","Hexed","Dead","1 use","No ability"],"setup":false,"otherNightReminder":"If a player is marked ''hexed'': they die. If the GOC Physics has not yet fully used their ability: The GOC Physics shows a ''no'' head signal, or shows a ''yes'' head signal. If the GOC Physics showed a ''yes'' head signal, mark them ''Trap set''.","art":"art/goc-physics.png","jsonId":"gocphysics_scp_fragmented_veil","curata":false}','scp-fragmented-veil/goc-physics','published',datetime('now'),datetime('now')),
('pinky','Pinky','townsfolk','legitch, cocofleur49',NULL,'','SCP Fragmented Veil','{"slug":"pinky","name":"Pinky","team":"townsfolk","ability":"Each night*, choose a player and a character: if correct, they die & you are drunk (unless the game ends.)","creator":"legitch, cocofleur49","appearsIn":"SCP Fragmented Veil","lede":"The self-destructive Pinky explodes- ka-boom!","summaryBullets":["The Pinky chooses a player and a character. If that player is that character, they''ll die, but the Pinky is drunk from then on, continuing to wake from then on.","If the Pinky''s kill would result in the immediate end of the game {{i|(such as by killing the Demon)}}, it doesn''t occur, but the Pinky won''t be drunk."],"howToRun":["Each night except the first, wake the Pinky. They point at any player, then point at any character icon on their character sheet. Put the Pinky to sleep. If the chosen player is that character from the chosen character icon, and the game won''t end immediately as a result of this final action, they {{i|die}} - mark them with the **DEAD** reminder and then the Pinky with the **DRUNK** reminder."],"quote":"What''s better than a conga line? A dead one!","iconBy":"lumihopehill","customBoxes":[{"title":"Alternative JSON & How to Run (Older)","content":"For if you want the Pinky to be more chaotic in their blast, including devastation and potential damage against the Demon, use this JSON.\n\nEach night except the first, wake the Pinky. They either shake their head no or yes. Put the Pinky to sleep.\n\nIf the Pinky shook their head yes, they die - mark them with the DEAD reminder, the NO ABILITY reminder, and remove their night token from the night sheet. If the Pinky successfully has the DEAD reminder token applied to them, their living neighbours die - also mark them with the DEAD reminders. Do not mark the Demon with it unless at-least one other marked player is evil.\n\n**Pinky █+** (Townsfolk)\nOnce per game, at night*, you may choose to die and take your living neighbours with you. You can''t kill a Demon as the only evil.\n\n**Other nights:** If the Pinky has not yet used their ability: The Pinky either shows the ''no'' head signal, or a ''yes'' signal. They and their living neighbours die.\n**Reminders:** Dead, Dead, Dead, No ability\n**Credit:** Ability: @legitch & [REDACTED AT REQUEST]. Image: @lumihopehill"}],"firstNight":0,"otherNight":54.1,"reminders":["Dead","Drunk"],"setup":false,"otherNightReminder":"The Pinky points to a player, and a character on their sheet. If correct, that player dies (unless it causes the immediate end of the game).","art":"art/pinky.png","jsonId":"pinky_scp_fragmented_veil","curata":false}','scp-fragmented-veil/pinky','published',datetime('now'),datetime('now')),
('premonious','Premonious','outsider','legitch',NULL,'','SCP Fragmented Veil','{"slug":"premonious","name":"Premonious","team":"outsider","ability":"You start knowing how you''ll die. If you avoid your fate, 1 player dies at any time.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"The Premonious knows the worst knowledge any man can learn; how they will die.","summaryBullets":["The Premonious learns their given fate, and if they fail to oblige by it, it shoots you down and corrects your behaviour.","The fate given the Premonious may be as generic, specific, or even cryptic as the Storyteller wants.","This can include the how, why, when, who, and if playing in real life, maybe even where.","When this ending to your life is no longer possible, whether the conditions for it can no longer be met, or the Premonious has died outside of it, 1 player will die at any time.","Should there be any possible way to resurrect a Premonious as they die outside of their fated death, they are not considered as having avoided their fate. However, once that method is also gone and the Premonious'' fate remains unfulfillable, then its considered as avoiding fate, and the punishment is applied.","The player that dies to the Premonious'' circumstances can be anyone, regardless of alignment or character type, but is typically a Townsfolk or Outsider.","The death caused by the Premonious can occur at any time, such as day or night. It can even kill them during the night before they can be protected by another character to prevent any deaths."],"howToRun":["During setup, decide the Premonious'' fate of how they die and write it on a piece of paper, or on a phone.","During the first night, wake the Premonious. Show this phrase, then put them to sleep.","When the conditions for this event are no longer possible by any means, even as the Premonious is dieing, or is dead, {{i|one player is dieing at any time}} - mark the Premonious with the **AVOIDED FATE** reminder token.","At any time, whilst the **AVOIDED FATE** reminder token is active, you may decide for **any player** to die. When you do so, use the **DEAD** reminder token to remind yourself that the Premonious'' ability has killed a player."],"tips":["Read into the evil team''s wants and intents when using the Premonious'' kill to benefit them. Remember that the Premonious may sometimes net themselves an early advantage by learning of a particular in-play character, or even a hint into what character a player is. It is advised that you hint at the fact that evil players may have some say over how this kill is used later on should it be primed & active for use."],"quote":"A moment to gather my thoughts, please. ... Alright, let''s do this.","iconBy":"le_nuberto","jinxes":[{"name":"Recursion","align":"evil","text":"If the Recursion chooses the Fisherman with various pieces of information, their ability will yield advice that implicates some facts using that information.","slug":"recursion"}],"firstNight":12.028,"otherNight":0,"reminders":["Avoided fate","Dead"],"setup":false,"firstNightReminder":"Show the Premonious their fate.","art":"art/premonious.png","jsonId":"premonious_scp_fragmented_veil","curata":false}','scp-fragmented-veil/premonious','published',datetime('now'),datetime('now')),
('world-hopper','World-Hopper','outsider','legitch',NULL,'','SCP Fragmented Veil','{"slug":"world-hopper","name":"World-Hopper","team":"outsider","ability":"On the 3rd night, the evil players become off script official characters. You learn which 1s (if alive) or 1 of 2 (if dead).","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"The World-Hopper (SCP-507) unwillingly teleports to another dimension, entering a new world of different threats that might not even be human.","summaryBullets":["The World-Hopper will \"teleport\" on Night 3 and change the evil team''s characters, without the Demon''s discretion or acceptance.","The World-Hopper''s ability acts late at night, being after most character abilities go through, and just before dawn occurs.","This will occur, even if they''re currently dead, but not if drunk or poisoned.","Evil players do not get any choice of what characters they''ll be if they accept the World-Hopper''s teleport, they''re in for the ride, or they''re not {{i|(coward)}}.","The characters that evil players can become due to the World-Hopper may only be ones officially released.","Additionally, the characters that evil players can become do not necessarily have to be Minions & Demons exclusively, some may even be evil Townsfolk or Outsiders.","Once this all occurs, the World-Hopper will directly learn what the characters are, but if currently dead, they instead learn 2 characters: 1 is true, the other is false."],"howToRun":["When preparing the first night, put the World-Hopper''s **NIGHT 1** reminder by the World-Hopper. When preparing the second night, put the World-Hopper''s **NIGHT 2** reminder by the World-Hopper. When preparing the third night, put the World-Hopper''s **NIGHT 3** reminder by the World-Hopper.","If the World-Hopper died due to an evil player''s ability, mark them with the **DISARMED** reminder.","During the night, even if the World-Hopper is dead, if the World-Hopper has the **NIGHT 3** reminder, swap the character tokens of evil players you choose with new official character tokens, including off-script. Wake each evil player that changed character, show the **YOU ARE** info token, then their new character token, then put them to sleep. Wake the World-Hopper, show them each of evil player''s character tokens {{i|(if they''re dead, show them 2 instead, 1 true, and 1 false.)}} Put the World-Hopper to sleep."],"tips":["It''s generally a good idea to pair the World-Hopper in scripts where the evil team has abilities that are limited in use or don''t have as much effectiveness later in the game {{i|(Ex. Assassin, Godfather, Spy, Baron)}}.","When you can, try turning Minions into Townsfolk or Outsiders with abilities that can serve the evil team quite well in their own right. Whilst there aren''t many in this regard, a few examples include the Philosopher, Sailor, Fisherman, and Plague Doctor."],"quote":"Yeah, so... that agent assigned to escort me to my chambers... he''s uhh... kinda... gone... forever. Oops.","iconBy":"le_nuberto","jinxes":[{"name":"Legion","align":"evil","text":"Only 1 jinxed character can be in play.","id":"legion"},{"name":"Riot","align":"evil","text":"The World-Hopper''s ability instead activates on midway through the 2nd night, but the original Riot is unaffected.","id":"riot"},{"name":"Matsuraid","align":"evil","text":"Only 1 jinxed character can be in play.","id":"matsuraid_hblreleased"},{"name":"Au’Wre","align":"evil","text":"If the World-Hopper activates, the Au''wre is in play & they accept the character change, the evil team learns each other.","id":"auwre_the_bootleggers_anthology"},{"name":"Tao Wu","align":"evil","text":"If the World-Hopper activates, the Tao Wu is in play & they accept the character change, any Minion that lost their ability due to the Tao Wu ability dies immediately.","id":"taowu_festival_of_lanterns"}],"customBoxes":[{"title":"In the almanac JSON","content":"**Other nights:** If it is the 3rd night and the World-Hopper is not marked ''Disarmed'', replace the evil team with characters of your choice, then wake the relevant Minions and/or Demon and show them the ''You are'' card and the relevant character tokens. Wake the World-Hopper, even if they''re dead. Show them the evil team''s new character tokens, but if they''re dead, also show a different character token before or after."}],"firstNight":0,"otherNight":92.507,"reminders":["Night 1","Night 2","Night 3"],"setup":false,"otherNightReminder":"If it is the 3rd night and the World-Hopper is not marked ''Disarmed'', replace the evil team with characters of your choice, then wake the relevant Minions and/or Demon and show them the ''You are'' card and the relevant character tokens. Wake the World-Hopper, even if they''re dead. Show them all evil player''s new character tokens, but if they''re dead, also show a different character token before or after.","art":"art/world-hopper.png","jsonId":"worldhopper_scp_fragmented_veil","curata":false}','scp-fragmented-veil/world-hopper','published',datetime('now'),datetime('now'));
